<div class="d-flex justify-content-between align-items-center mb-3"><div><h1 class="h3">Users & Roles</h1><p class="text-secondary mb-0">Server-side authorization, users and role permissions.</p></div></div>
<div class="row g-3"><div class="col-lg-7"><div class="card shadow-sm"><div class="card-header"><strong>Users</strong></div><div class="card-body"><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Username</th><th>Name</th><th>Role</th><th>Status</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=e($u['username'])?></td><td><?=e($u['full_name'])?></td><td><?=e($u['role_name'])?></td><td><?=e($u['active']?'Active':'Inactive')?></td></tr><?php endforeach;?></tbody></table></div>
<form id="uf" class="border-top pt-3 mt-3"><div class="row g-2"><div class="col-md-4"><input name="username" class="form-control" placeholder="Username" required></div><div class="col-md-4"><input name="full_name" class="form-control" placeholder="Full name" required></div><div class="col-md-4"><select name="role_id" class="form-select"><?php foreach($roles as $r):?><option value="<?=$r['id']?>"><?=e($r['name'])?></option><?php endforeach;?></select></div><div class="col-md-4"><input name="password" type="password" class="form-control" placeholder="Password (new user required)"></div><div class="col-md-4"><input name="default_counter_id" class="form-control" placeholder="Default counter ID"></div><div class="col-md-4"><select name="active" class="form-select"><option value="1">Active</option><option value="0">Inactive</option></select></div></div><button class="btn btn-primary mt-2">Save User</button></form></div></div></div>
<div class="col-lg-5"><div class="card shadow-sm"><div class="card-header"><strong>Role Permissions</strong></div><div class="card-body"><select id="role" class="form-select mb-2"><?php foreach($roles as $r):?><option value="<?=$r['id']?>"><?=e($r['name'])?></option><?php endforeach;?></select><div id="perms" style="max-height:430px;overflow:auto"><?php foreach($permissions as $p):?><div class="form-check"><input class="form-check-input perm" type="checkbox" value="<?=$p['id']?>" data-module="<?=e($p['module'])?>"><label class="form-check-label"><?=e($p['module'].' · '.$p['code'])?></label></div><?php endforeach;?></div><button id="savePerms" class="btn btn-outline-primary mt-3">Save Permissions</button></div></div></div></div>
<script>
$(function(){const b=<?=json_encode(url('/'),JSON_THROW_ON_ERROR)?>;function load(){$.getJSON(b+'users/roles/'+$('#role').val()+'/permissions').done(r=>{let ids=(r.data||[]).map(x=>String(x.permission_id));$('.perm').each(function(){$(this).prop('checked',ids.includes(String(this.value)))})})}$('#role').change(load);$('#uf').submit(function(e){e.preventDefault();$.post(b+'users',$(this).serialize()).done(r=>{alert(r.message);if(r.ok)location.reload()}).fail(x=>alert(x.responseJSON?.message||'Save failed'))});$('#savePerms').click(function(){let a=$('.perm:checked').map(function(){return this.value}).get();$.post(b+'users/roles/'+$('#role').val()+'/permissions',{permission_ids:a}).done(r=>alert(r.message)).fail(x=>alert(x.responseJSON?.message||'Save failed'))});load();});
</script>